package com.collabspace.service;
import com.collabspace.dto.MessageDtos.*; import com.collabspace.entity.*; import com.collabspace.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor public class DirectMessageService {private final DirectConversationRepository conversations;private final DirectMessageRepository messages;private final UserRepository users;private final CurrentUserService current; public DirectConversation conversation(UUID other){User me=current.get();User them=users.findById(other).orElseThrow(()->new NoSuchElementException("User not found"));return conversations.findByUserOneIdAndUserTwoId(me.getId(),other).orElseGet(()->conversations.findByUserOneIdAndUserTwoId(other,me.getId()).orElseGet(()->conversations.save(DirectConversation.builder().userOne(me).userTwo(them).build())));} @Transactional public DirectMessageResponse send(UUID other,SendDirectMessageRequest r){var c=conversation(other);var m=messages.save(DirectMessage.builder().conversation(c).sender(current.get()).content(r.content().trim()).build());return dto(m);} public Page<DirectMessageResponse> history(UUID other,int page,int size){var c=conversation(other);return messages.findByConversationIdAndDeletedFalseOrderByCreatedAtDesc(c.getId(),PageRequest.of(Math.max(page,0),Math.min(Math.max(size,1),100))).map(this::dto);} public DirectMessageResponse dto(DirectMessage m){return new DirectMessageResponse(m.getId(),m.getConversation().getId(),m.getSender().getId(),m.getSender().getUsername(),m.isDeleted()?"This message was deleted":m.getContent(),m.getCreatedAt(),m.isEdited(),m.isDeleted(),m.getReadStatus().name());}}
